WITH ValidInventory AS (SELECT * FROM inventory WHERE product_id IN (3, 8)), summary AS (SELECT YEAR(last_restock) last_restock_year, MIN(last_restock) min_last_restock, COUNT(*) inventory_count FROM ValidInventory GROUP BY YEAR(last_restock)) SELECT last_restock_year, min_last_restock, inventory_count FROM summary WHERE inventory_count < 6 ORDER BY min_last_restock DESC, last_restock_year LIMIT 3;
